Point toFundamentalDomainTriangle(Point point, out int reflectionCount){
    reflectionCount = 0;
    for (int steps=0; steps<32; steps++){
        if (steps >= u_maxIterations) break;
        int extra =
            reflectThrough(point, reflection1, point) +
            reflectThrough(point, reflection2, point) +
            reflectThrough(point, reflection3, point);
