    float d = float(depth) / 20.0;
    return hsv2rgb(vec3(mod(d * u_fractalDepth, 1.0), 0.8, 0.9));
}
void main()
{
    createReflections();
    bool outOfBounds;
    Point uv = toSpaceCoordinate(gl_FragCoord.xy, outOfBounds);
    if (outOfBounds){
        gl_FragColor = vec4(0.1, 0.1, 0.12, 1.);
        return;
    }
    uv = spaceDynamics(uv);
    int reflectionCount = 0;
    vec2 v = fromSpaceCoordinate(toFundamentalDomainTriangle(uv, reflectionCount));
    v *= u_textureDynamics[0];
    v = rotation(u_textureDynamics[1])*v;
    v += vec2(u_textureDynamics[2], u_textureDynamics[3]);
    vec3 pixel = pixelColor(v);
    if (u_showTriangle){
        float mainTriangle = 1.-min(float(reflectionCount),1.);
        gl_FragColor = vec4(mainTriangle*vec3(1.),1.0);
        return;
    }
    float reflectionCountMod2 = mod(float(reflectionCount), 2.0);
    if (u_trianglesShadow<=1.){
        pixel *= (2.-reflectionCountMod2*u_trianglesShadow)/2.;
    } else {
        pixel *= (2.-reflectionCountMod2)/2.;
        pixel = mix(pixel, vec3(1.-reflectionCountMod2), u_trianglesShadow-1.);
    }
    if (u_fractalDepth > 0.0) {
        vec3 dc = depthColor(reflectionCount);
        pixel = mix(pixel, dc, u_fractalDepth * 0.5);
    }
    if (u_edgeGlow > 0.0) {
        float edgeDist = min(min(abs(v.x - floor(v.x + 0.5)), abs(v.y - floor(v.y + 0.5))), 0.5);
        float edge = smoothstep(u_edgeThickness, 0.0, edgeDist);
        pixel += vec3(edge * u_edgeGlow);
    }
    float pulse = 1.0 + sin(u_time * u_pulse) * u_pulseAmount;
    pixel *= pulse;
    if (u_colorModeVal == 1) {
        pixel = vec3(dot(pixel, vec3(0.299, 0.587, 0.114)));
    } else if (u_colorModeVal == 2) {
        pixel = 1.0 - pixel;
    } else if (u_colorModeVal == 3) {
        vec3 hsv = rgb2hsv(pixel);
        hsv.x = mod(hsv.x + float(reflectionCount) * 0.08, 1.0);
        pixel = hsv2rgb(hsv);
    } else if (u_colorModeVal == 4) {
        float gray = dot(pixel, vec3(0.299, 0.587, 0.114));
        pixel = vec3(gray < 0.5 ? 0.0 : 1.0);
    } else if (u_colorModeVal == 5) {
        pixel = floor(pixel * 4.0) / 4.0;
    } else if (u_colorModeVal == 6) {
        pixel = vec3(pixel.r, pixel.g * 0.5, pixel.b * 0.8);
    }
    vec3 hsv = rgb2hsv(pixel);
    hsv.x = mod(hsv.x + u_hueShift, 1.0);
    hsv.y *= u_saturationVal;
