var fxaaFragShader = `
precision highp float;
uniform sampler2D u_texture;
uniform vec2 u_resolution;
uniform int u_aaLevel;
uniform float u_chromaAberration;
varying vec2 vTexCoord;
const float FXAA_SPAN_MAX = 8.0;
const float FXAA_REDUCE_MUL = 1.0/8.0;
const float FXAA_REDUCE_MIN = 1.0/128.0;
vec3 sampleTexture(vec2 uv) {
    if (u_chromaAberration > 0.0) {
        vec2 dir = uv - 0.5;
        float r = texture2D(u_texture, uv + dir * u_chromaAberration * 0.01).r;
        float g = texture2D(u_texture, uv).g;
        float b = texture2D(u_texture, uv - dir * u_chromaAberration * 0.01).b;
        return vec3(r, g, b);
    }
    return texture2D(u_texture, uv).rgb;
}
vec3 fxaa(vec2 fragCoord, vec2 resolution) {
    vec2 inverseVP = 1.0 / resolution;
    vec2 uv = fragCoord * inverseVP;
    vec3 rgbNW = sampleTexture(uv + vec2(-1.0, -1.0) * inverseVP);
    vec3 rgbNE = sampleTexture(uv + vec2(1.0, -1.0) * inverseVP);
    vec3 rgbSW = sampleTexture(uv + vec2(-1.0, 1.0) * inverseVP);
    vec3 rgbSE = sampleTexture(uv + vec2(1.0, 1.0) * inverseVP);
    vec3 rgbM  = sampleTexture(uv);
    vec3 luma = vec3(0.299, 0.587, 0.114);
    float lumaNW = dot(rgbNW, luma);
    float lumaNE = dot(rgbNE, luma);
    float lumaSW = dot(rgbSW, luma);
    float lumaSE = dot(rgbSE, luma);
    float lumaM  = dot(rgbM, luma);
    float lumaMin = min(lumaM, min(min(lumaNW, lumaNE), min(lumaSW, lumaSE)));
    float lumaMax = max(lumaM, max(max(lumaNW, lumaNE), max(lumaSW, lumaSE)));
    vec2 dir;
    dir.x = -((lumaNW + lumaNE) - (lumaSW + lumaSE));
    dir.y =  ((lumaNW + lumaSW) - (lumaNE + lumaSE));
    float dirReduce = max((lumaNW + lumaNE + lumaSW + lumaSE) * (0.25 * FXAA_REDUCE_MUL), FXAA_REDUCE_MIN);
    float rcpDirMin = 1.0 / (min(abs(dir.x), abs(dir.y)) + dirReduce);
    dir = min(vec2(FXAA_SPAN_MAX), max(vec2(-FXAA_SPAN_MAX), dir * rcpDirMin)) * inverseVP;
    vec3 rgbA = 0.5 * (sampleTexture(uv + dir * (1.0/3.0 - 0.5)) + sampleTexture(uv + dir * (2.0/3.0 - 0.5)));
    vec3 rgbB = rgbA * 0.5 + 0.25 * (sampleTexture(uv + dir * -0.5) + sampleTexture(uv + dir * 0.5));
    float lumaB = dot(rgbB, luma);
    if ((lumaB < lumaMin) || (lumaB > lumaMax))
        return rgbA;
    return rgbB;
}
void main() {
    vec2 fragCoord = vTexCoord * u_resolution;
    vec3 color;
    if (u_aaLevel == 0) {
        color = sampleTexture(vTexCoord);
    } else if (u_aaLevel == 1) {
        color = fxaa(fragCoord, u_resolution);
    } else {
        vec3 c1 = fxaa(fragCoord + vec2(-0.25, -0.25), u_resolution);
        vec3 c2 = fxaa(fragCoord + vec2(0.25, -0.25), u_resolution);
        vec3 c3 = fxaa(fragCoord + vec2(-0.25, 0.25), u_resolution);
        vec3 c4 = fxaa(fragCoord + vec2(0.25, 0.25), u_resolution);
        color = (c1 + c2 + c3 + c4) * 0.25;
    }
    gl_FragColor = vec4(color, 1.0);
}
