    shaders[HYPERBOLIC] = createShader(vertShader, shaderUniforms+HyperbolicGeometryShader+shaderGeneralFunctionality);
    shaders[SPHERICAL] = createShader(vertShader, shaderUniforms+SphericalGeometryShader+shaderGeneralFunctionality);
    theShader = shaders[geometry];
}

function setup() {
    createCanvas(windowWidth, windowHeight);
    pixelDensity(1);
    canvas = createGraphics(windowWidth, windowHeight, WEBGL);
    canvas.pixelDensity(1);
    fxaaBuffer = createGraphics(windowWidth, windowHeight, WEBGL);
    fxaaBuffer.pixelDensity(1);
    fxaaShader = fxaaBuffer.createShader(fxaaVertShader, fxaaFragShader);
    defaultTexture = createProceduralTexture();
    img = defaultTexture;
    background(0);
    setGroupHyperblic(2,3,7);
    setGroup(_l,_m,_n);
    setupGUI();
    fileInput = createFileInput(handleFile);
    fileInput.position(10, windowHeight - 40);
    fileInput.style('z-index', '9999');
    fileInput.style('background', 'rgba(60,60,80,0.9)');
    fileInput.style('color', '#fff');
    fileInput.style('padding', '8px 12px');
    fileInput.style('border', 'none');
    fileInput.style('border-radius', '4px');
    fileInput.style('cursor', 'pointer');
    fileInput.style('font-size', '12px');
}

function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
    canvas.resizeCanvas(windowWidth, windowHeight);
    fxaaBuffer.resizeCanvas(windowWidth, windowHeight);
    if (fileInput) {
        fileInput.position(10, windowHeight - 40);
    }
}

function handleFile(file) {
    if (file.type === 'image') {
        loadImage(file.data, function(loadedImg) {
            img = loadedImg;
        });
    }
}

