function normMat(M){
    return M[0][0]*M[0][0] + M[1][0]*M[1][0] + M[0][1]*M[0][1] + M[1][1]*M[1][1];
}

function multMat(M1, M2){
    var result = [[0,0],[0,0]];
    for (var i = 0; i < 2; i++){
        for (var j = 0; j < 2; j++){
            for (var k = 0; k < 2; k++){
                result[i][j] += M1[i][k]*M2[k][j];
            }
        }
    }
    return result;
}

function inverseMat(M){
    var d = M[0][0]*M[1][1]-M[0][1]*M[1][0];
    return [[M[1][1]/d, -M[0][1]/d],[-M[1][0]/d, M[0][0]/d]];
}

function rotationMat(angle){
    return [[cos(angle), sin(angle)],[-sin(angle),cos(angle)]];
}

function shearingMat(s){
    return [[1,s],[0,1]];
}

function _createHyperbolicGenerators(){
    var m = [];
    for (var i = 0; i < reflectionMatrices.length; i++){
        var mat = reflectionMatrices[i];
        m.push(multMat(mat,multMat(hypMinus,inverseMat(mat))));
    }
    hyperbolicGenerators = [];
    for (var i = 0; i < 3; i++){
        for (var j = 0; j < 3; j++){
            if (j==i) continue;
            hyperbolicGenerators.push(multMat(m[i],m[j]));
        }
    }
    hyperbolicDynMat = [[1,0],[0,1]];
}

function setGroupHyperblic(l,m,n){
    if (l==1){
        var x_N = n==1 ? 1 : cos(PI/n);
        var x_M = m==1 ? 1 : cos(PI/m);
        reflectionMatricesShader = [];
        reflectionMatrices = [];
        reflectionMatrices.push([[1,-x_M],[0,1]]);
        reflectionMatrices.push([[-1/sqrt(2),-1/sqrt(2)],[1/sqrt(2),-1/sqrt(2)]]);
        reflectionMatrices.push([[x_N,-1],[1,0]]);
        for (var i=0; i<3; i++){
            reflectionMatrices[i]=multMat(hypInverse,reflectionMatrices[i]);
        }
        _createHyperbolicGenerators();
        reflectionMatricesShader = reflectionMatrices.flat().flat();
        return true;
    }
    if (1/l + 1/m + 1/n >= 1)
        return false;
    var theta0 = PI/l;
    var theta1 = PI/m;
    var theta2 = PI/n;
    var b = (cos(theta0)*cos(theta1) + cos(theta2))/(sin(theta0)*sin(theta1));
    reflectionMatrices = [];
    var y0 = 1;
    var x0 = y0 / tan(theta0);
    var r0 = sqrt(y0*y0 + x0*x0);
    reflectionMatrices.push([[x0-r0, -(x0+r0)],[1, -1]]);
    var y1 = (b + sqrt(b*b - 1));
    var x1 = -y1 / tan(theta1);
    var r1 = sqrt(y1*y1 + x1*x1);
    reflectionMatrices.push([[x1+r1, x1-r1],[1, 1]]);
    reflectionMatrices.push([[1,0],[0,1]]);
    for (var i=0; i<3; i++){
        reflectionMatrices[i]=multMat(hypInverse,reflectionMatrices[i]);
    }
    _createHyperbolicGenerators();
    reflectionMatricesShader = reflectionMatrices.flat().flat();
    return true;
}

function setGroupEuclidean(l,m,n){
    if (l==1 && m==2 && n==2){
        reflectionPoints  = [0,0,  0,0,  1,0];
        reflectionNormals = [0,1,  1,0,  -1,0];
    }
    if (l==2 && m==4 && n==4){
        reflectionPoints  = [0,0,  0,0,  0.5,0.5];
        reflectionNormals = [0,1,  1,0,  -1/sqrt(2),-1/sqrt(2)];
        return true;
    }
    if (l==2 && m==3 && n==6){
        reflectionPoints  = [0,0,  0,0,  0.5,0];
        reflectionNormals = [0,1,  1,0,  -Math.sqrt(3)/2,-0.5];
        return true;
    }
    if (l==3 && m==3 && n==3){
        reflectionPoints  = [0,0,  0,0,             1,0];
        reflectionNormals = [0,1,  sqrt(3)/2,-0.5,  -sqrt(3)/2,-0.5];
        return true;
    }
    return false;
}

function setGroupSpherical(l,m,n){
    if (1/l + 1/m + 1/n <= 1)
        return false;
    reflectionNormals3D = [];
    reflectionNormals3D.push(1,0,0);
    reflectionNormals3D.push(-cos(PI/n),sin(PI/n),0);
    var temp = -( cos(PI/n)*cos(PI/m) + cos(PI/l) )/sin(PI/n);
    var zVal = 1-temp*temp-cos(PI/m)*cos(PI/m);
    if (zVal < 0) zVal = 0;
    reflectionNormals3D.push(-cos(PI/m), temp, sqrt(zVal));
    return true;
}

function setGroup(l,m,n){
    var sorted = [l,m,n].sort(function(a,b){return a-b;});
    var ll = sorted[0], mm = sorted[1], nn = sorted[2];
    if (ll<1) return false;
    _l = l; _m = m; _n = n;
    var numerator = ll*mm + mm*nn + nn*ll;
    var denominator = ll*mm*nn;
    if (ll==1 && mm==2 && nn==2){
        setGroupEuclidean(ll, mm, nn);
        geometry = EUCLIDEAN;
        theShader = shaders[geometry];
        return true;
    }
    if (ll==1 || numerator<denominator){
        setGroupHyperblic(ll, mm, nn);
        geometry = HYPERBOLIC;
        theShader = shaders[geometry];
        return true;
    }
    if (numerator>denominator){
        setGroupSpherical(ll, mm, nn);
        geometry = SPHERICAL;
        theShader = shaders[geometry];
        return true;
    }
    setGroupEuclidean(ll, mm, nn);
    geometry = EUCLIDEAN;
    theShader = shaders[geometry];
    return true;
}

function setEuclideanUniforms(){
    theShader.setUniform('u_reflectionPoints', reflectionPoints);
    theShader.setUniform('u_reflectionNormals', reflectionNormals);
    var t = tilingAnimationTime;
    theShader.setUniform('u_spaceDynamics', [0.5+(cos(t/6)-1)*0.1, t/4, 2*sin(t/7), 2*sin(t/3)]);
}

function setHyperbolicUniforms(){
    theShader.setUniform('u_reflectionMatrices', reflectionMatricesShader);
    var t = tilingAnimationTime;
    var m = multMat(shearingMat(t/2), rotationMat(-t/2));
    theShader.setUniform('u_poincare', poincarePres);
    m = multMat(hyperbolicDynMat, m);
    if (frameCount%60==0){
        var normM = normMat(m);
        for (var i = 0; i < hyperbolicGenerators.length; i++){
            var generator = hyperbolicGenerators[i];
            var newNorm = normMat(multMat(generator,m));
            if (newNorm<normM-1){
                hyperbolicDynMat = multMat(generator, hyperbolicDynMat);
            }
        }
    }
    theShader.setUniform('u_spaceDynamics', m.flat());
}

function setSphericalUniforms(){
    theShader.setUniform('u_reflectionNormals3D', reflectionNormals3D);
    var t = tilingAnimationTime;
    theShader.setUniform('u_angles',[0,t/3,t/2]);
}

function setGeometryUniforms(){
    switch (geometry){
        case EUCLIDEAN:
            setEuclideanUniforms();
            break;
        case HYPERBOLIC:
            setHyperbolicUniforms();
            break;
        case SPHERICAL:
            setSphericalUniforms();
            break;
    }
}

function draw() {
    if (_l!=lVal || _m!=mVal || _n!=nVal){
        if (setGroup(lVal, mVal, nVal)){
            tilingAnimationTime = 0;
            textureAnimationTime = 0;
        }
    }
    tilingAnimationTime += 0.05*tileAnimSpeed;
    textureAnimationTime += 0.02*texAnimSpeed;
    var staticRotation = frameCount * rotateSpeed * 0.01;
    background(30);
    theShader.setUniform('u_resolution', [width, height]);
    theShader.setUniform('u_density', pixelDensity());
    theShader.setUniform('u_time', frameCount/100);
    theShader.setUniform('u_zoom', zoomVal);
    theShader.setUniform('u_texture', img);
    theShader.setUniform('u_trianglesShadow', triangleShadow);
    theShader.setUniform('u_showTriangle', showTriangle);
    theShader.setUniform('u_hueShift', hueShiftVal);
    theShader.setUniform('u_saturationVal', saturationVal);
    theShader.setUniform('u_brightnessVal', brightnessVal);
    theShader.setUniform('u_contrast', contrastVal);
    theShader.setUniform('u_edgeGlow', edgeGlowVal);
    theShader.setUniform('u_edgeThickness', edgeThicknessVal);
    theShader.setUniform('u_kaleidoscope', kaleidoSegments);
    theShader.setUniform('u_distortion', distortAmount);
    theShader.setUniform('u_distortionFreq', distortFreq);
    theShader.setUniform('u_vignette', vignetteVal);
    theShader.setUniform('u_chromaAberration', chromaAberr);
    theShader.setUniform('u_pulse', pulseSpeedVal);
    theShader.setUniform('u_pulseAmount', pulseAmountVal);
    theShader.setUniform('u_invert', invertColorsVal);
    theShader.setUniform('u_mirrorX', mirrorXVal);
    theShader.setUniform('u_mirrorY', mirrorYVal);
    theShader.setUniform('u_rotation', staticRotation);
    theShader.setUniform('u_spiralTwist', spiralTwist);
    theShader.setUniform('u_mobiusA', mobiusParamA);
    theShader.setUniform('u_mobiusB', mobiusParamB);
    theShader.setUniform('u_waveAmp', waveAmplitude);
    theShader.setUniform('u_waveFreq', waveFrequency);
    theShader.setUniform('u_fisheyeAmount', fisheyeWarp);
    theShader.setUniform('u_triangleScale', triangleScaleVal);
    theShader.setUniform('u_fractalDepth', fractalDepthColor);
    theShader.setUniform('u_maxIterations', maxIter);
    theShader.setUniform('u_domainWarp', 0);
    theShader.setUniform('u_radialRepeat', 1);
    theShader.setUniform('u_spherize', 0);
    var colorModes = ['Normal', 'Grayscale', 'Inverted', 'Rainbow', 'Threshold', 'Posterize', 'Cyberpunk'];
    var colorIdx = colorModes.indexOf(colorModeType);
    theShader.setUniform('u_colorModeVal', colorIdx >= 0 ? colorIdx : 0);
    var t = textureAnimationTime;
    theShader.setUniform('u_textureDynamics', [
        (cos(t/10)-1)*0.2 + 1,
        t/3,
        2*sin(t/4), 2*sin(-t/5)
    ]);
    setGeometryUniforms();
    canvas.shader(theShader);
    canvas.rect(0,0,width,height);
    var aaLevel = 0;
    if (aaMode === 'FXAA') aaLevel = 1;
    else if (aaMode === 'FXAA x2') aaLevel = 2;
    if (aaLevel > 0) {
        fxaaBuffer.shader(fxaaShader);
        fxaaShader.setUniform('u_texture', canvas);
        fxaaShader.setUniform('u_resolution', [width, height]);
        fxaaShader.setUniform('u_aaLevel', aaLevel);
        fxaaShader.setUniform('u_chromaAberration', chromaAberr);
        fxaaBuffer.rect(0,0,width,height);
        image(fxaaBuffer,0,0);
    } else {
        image(canvas,0,0);
    }
}

function keyPressed(){
    if (key == 't' || key == 'T'){
        showTriangle = !showTriangle;
    }
    if (key == 'p' || key == 'P'){
        poincarePres = !poincarePres;
        OPC.set('poincarePres', poincarePres);
    }
    if (key == 's' || key == 'S'){
        saveCanvas(canvas, 'triangle_group_'+frameCount, 'png');
    }
    if (key == 'f' || key == 'F'){
        var fs = fullscreen();
        fullscreen(!fs);
    }
    if (key == 'r' || key == 'R'){
        img = defaultTexture;
    }
}

